questions = []

def add(q_id, q_num, question, opt_a, opt_b, opt_c, opt_d, correct_ans, explanation, difficulty, subtopic, is_pyq=False, pyq_year=None):
    correct_idx = ["A", "B", "C", "D"].index(correct_ans)
    q = {
        "id": q_id,
        "questionNumber": q_num,
        "question": question,
        "options": {
            "A": opt_a,
            "B": opt_b,
            "C": opt_c,
            "D": opt_d
        },
        "optionsList": [opt_a, opt_b, opt_c, opt_d],
        "correctAnswer": correct_ans,
        "correctIndex": correct_idx,
        "explanation": explanation,
        "difficulty": difficulty,
        "subject": "Chemistry",
        "class": "11",
        "chapter": "Chemical Thermodynamics",
        "chapterId": "thermodynamics-chem",
        "topicId": "chem-enthalpies-reaction",
        "subtopic": subtopic,
        "isPyq": is_pyq,
        "isVerifiedPyq": is_pyq
    }
    if is_pyq and pyq_year:
        q["pyqDetails"] = {
            "exam": "NEET UG",
            "year": pyq_year,
            "shift": "Single Shift"
        }
    questions.append(q)

